package com.nspay.finance;
import com.nspay.entities.AccountStatus;
import lombok.Data;
import org.springframework.web.bind.annotation.*;
import javax.servlet.http.HttpServletRequest;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import java.util.*;
@io.swagger.v3.oas.annotations.tags.Tag(name="Security and account restrictions")
@RestController @RequestMapping("/api/security")
public class SecurityController {
    private final SecurityService security;private final PaymentSignalService signals;
    public SecurityController(SecurityService s,PaymentSignalService signals){security=s;this.signals=signals;}
    private long id(HttpServletRequest r){Object id=r.getAttribute("authenticatedUserId");if(!(id instanceof Number))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return ((Number)id).longValue();}
    @io.swagger.v3.oas.annotations.media.Schema(name="SecurityDecision")
    @Data public static class Decision {private AccountStatus status;@io.swagger.v3.oas.annotations.media.Schema(minimum="30",maximum="90",example="30",description="Required only for SUSPENDED. A second suspension becomes BLOCKED.") private Integer days;@io.swagger.v3.oas.annotations.media.Schema(minLength=5,maxLength=250,example="Confirmed unauthorized account activity",description="Required internal decision reason, visible to the affected customer and administrators.") private String reason;private boolean confirmed;@io.swagger.v3.oas.annotations.media.Schema(maxLength=250,description="Optional note shown to all customers after a restriction changes.") private String publicNote;@io.swagger.v3.oas.annotations.media.Schema(maxLength=250,description="Optional note for the affected customer and authorized administrators only.") private String privateNote;}
    @GetMapping @io.swagger.v3.oas.annotations.Operation(summary="Get customer security reports and activity", description="Regular users only. Returns owned reports, restriction/history and the latest 50 public administrator account actions. Other users’ reasons, transaction IDs and private notes are omitted on the server. Reporting alone does not restrict an account.")
    @io.swagger.v3.oas.annotations.responses.ApiResponse(responseCode="200",description="Successful response",content=@io.swagger.v3.oas.annotations.media.Content(mediaType="application/json",schema=@io.swagger.v3.oas.annotations.media.Schema(implementation=com.nspay.config.ApiViews.SecurityState.class)))
    public Map<String,Object> own(HttpServletRequest r){return security.own(id(r));}
    @GetMapping("/users") @io.swagger.v3.oas.annotations.Operation(summary="Get the administrator user directory", description="Administrator only. Returns account status, balance and suspension metadata. Card numbers are masked on the server to their last four digits.")
    @io.swagger.v3.oas.annotations.responses.ApiResponse(responseCode="200",description="Successful response",content=@io.swagger.v3.oas.annotations.media.Content(mediaType="application/json",array=@io.swagger.v3.oas.annotations.media.ArraySchema(schema=@io.swagger.v3.oas.annotations.media.Schema(implementation=com.nspay.config.ApiViews.DirectoryEntry.class))))
    public List<Map<String,Object>> users(HttpServletRequest r){return security.directory(id(r));}
    @GetMapping("/reports") @io.swagger.v3.oas.annotations.Operation(summary="Get the security review queue", description="Administrator only. Returns the latest 100 security reports.")
    public List<SecurityReport> reports(HttpServletRequest r){return security.queue(id(r));}
    @GetMapping("/payments") @io.swagger.v3.oas.annotations.Operation(summary="Filter and sort the administrator payment review queue", description="Stored administrator role required. Paged scored payments for all users, with 0–100 amount, UTC-hour timing, one-hour velocity, recipient novelty, reporting and combined misalignment metrics. Base weights: 35/15/15/15/20 percent. Daily outgoing usage adds up to 25 points (limitScore × 0.25), capped at 100 overall; count and EUR usage at the payment time are returned with their limits. limitScore is zero below 80%, 25–59 near the threshold, 60 at 100%, and up to 100 above the threshold. Historic decisions retain their score snapshot. Customer reports increase signals but never restrict accounts automatically. At most 200 unscored payments are indexed per request; indexing indicates remaining backlog. Score/state/report/type/search filters and whitelisted sorting are server-side. Scores are triage heuristics, not fraud probabilities.")
    @io.swagger.v3.oas.annotations.responses.ApiResponse(responseCode="200",description="Paged payment signals",content=@io.swagger.v3.oas.annotations.media.Content(schema=@io.swagger.v3.oas.annotations.media.Schema(implementation=com.nspay.config.ApiViews.PaymentQueue.class)))
    public Map<String,Object> payments(HttpServletRequest r,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="All") String state,@RequestParam(defaultValue="all") String reported,@RequestParam(defaultValue="misalignmentScore") String sort,@RequestParam(defaultValue="desc") String direction,@RequestParam(defaultValue="0") int minScore,@RequestParam(defaultValue="misalignmentScore") String metric,@RequestParam(defaultValue="") String type){return signals.queue(id(r),page,size,search,state,reported,sort,direction,minScore,metric,type);}
    @GetMapping("/transactions/{transaction}/evidence") @io.swagger.v3.oas.annotations.Operation(summary="Inspect payment signals and related customer reports",description="Administrator only. Returns the payment’s stored score snapshot and at most 50 customer reports for that transaction or the same recipient IBAN, including reporter usernames, reasons and review states. Customers cannot read this evidence or other customers’ report reasons.")
    public Map<String,Object> evidence(HttpServletRequest r,@PathVariable long transaction){return signals.evidence(id(r),transaction);}
    @PostMapping("/transactions/{transaction}/review") @io.swagger.v3.oas.annotations.Operation(summary="Review a scored payment and optionally restrict its account", description="Administrator only. Null status dismisses; FREEZE, SUSPENDED or BLOCKED confirms a restriction. Reason is required; optional public/private notes have separate visibility. Locks account then signal; decision, report resolution, restriction/history and audit commit atomically. Repeated review returns 409. Existing suspensions/blocks are never weakened; a second distinct suspension becomes BLOCKED. A report is not required to review a payment.")
    public PaymentSignal reviewPayment(HttpServletRequest r,@PathVariable long transaction,@RequestBody Decision d){return security.reviewPayment(id(r),transaction,d.getStatus(),d.getDays(),d.getReason(),d.getPublicNote(),d.getPrivateNote());}
    @PostMapping("/transactions/{transaction}/report") @io.swagger.v3.oas.annotations.Operation(summary="Report an owned transaction for administrator review", description="Regular users only, with ownership checked from the authenticated account. Creates one case, records a reporting signal and audit entry, and leaves account access unchanged. Repeat submissions return the existing case. A report is not confirmation of fraud; only an administrator can impose a restriction.")
    public SecurityReport report(HttpServletRequest r,@PathVariable long transaction,@RequestBody Decision d){return security.report(id(r),transaction,d.getReason());}
    @PostMapping("/users/{subject}/status") @io.swagger.v3.oas.annotations.Operation(summary="Set a user’s account status", description="Administrator only. Allowed statuses: ACTIVE, FREEZE, SUSPENDED, BLOCKED. A reason of 5–250 characters is required. SUSPENDED requires 30–90 days. A second suspension becomes BLOCKED automatically. Explicitly restoring ACTIVE does not reset the count. Status, restriction metadata and history commit atomically.")
    public AccountRestriction status(HttpServletRequest r,@PathVariable long subject,@RequestBody Decision d){return security.setStatus(id(r),subject,d.getStatus(),d.getDays(),d.getReason(),d.getPublicNote(),d.getPrivateNote());}
    @PostMapping("/reports/{report}/review") @io.swagger.v3.oas.annotations.Operation(summary="Review a report through the payment review workflow", description="Administrator only. Legacy adapter: confirmed=false dismisses without changing account access; confirmed=true freezes, or suspends if days is provided. Repeated reviews return 409. Prefer the scored transaction review endpoint for explicit status and separate public/private notes.")
    public SecurityReport review(HttpServletRequest r,@PathVariable long report,@RequestBody Decision d){return security.review(id(r),report,d.isConfirmed(),d.getDays(),d.getReason());}
}
